(function(E){ const x = E["ai-m4"] = E["ai-m4"] || {units:{}}; x.units["ai-13"] = {"grammar":{"id":"c-ai-13-g","level":"B1","course":"ai-internet","unit":"ai-13","title":"Noun + noun, and for X, start with Y","titleTr":"İsim + isim ve for X, start with Y","titleFa":"اسم + اسم و for X, start with Y","formsTable":{"headers":{"en":["Not this","This"],"tr":["Bu değil","Bu"],"fa":["این نه","این"]},"rows":[["warranty of a chair","chair warranty"],["period of warranty","warranty period"],["price of delivery","delivery price"]]},"wrong":"warranty of office chair","right":"office chair warranty","blank":{"sentence":"Search for: office ___ warranty","word":"chair","distractors":["of chair","chair's of"]},"wrong2":"For specifications, start from the forum.","right2":"For specifications, start with the datasheet.","blank2":{"sentence":"For research, start ___ Google Scholar.","word":"with","distractors":["at of","to"]},"expParts":{"tryFrom":"blank","rule":[{"en":"The describing noun goes first, with no of.","tr":"Niteleyen isim öne gelir, of olmadan.","fa":"اسم توصیفی اول می‌آید، بدون of.","ex":"chair warranty"},{"en":"Recommend a place with for + noun, start with.","tr":"Yeri for + isim, start with ile öner.","fa":"جا را با for + اسم، start with پیشنهاد بده.","ex":"For specifications, start with the datasheet."}],"test":{"en":"Can you drop of and swap the nouns?","tr":"of'u atıp isimlerin yerini değiştirebilir misin?","fa":"می‌توانی of را حذف کنی و جای اسم‌ها را عوض کنی؟"},"contrast":{"en":"Persian and Turkish often put the main noun first or use a suffix. English search terms put the describing noun first: chair warranty.","tr":"Türkçede \"sandalye garantisi\" derken ek kullanılır. İngilizcede ek yoktur, sıra yeter: chair warranty.","fa":"در فارسی می‌گوییم «گارانتی صندلی»، با اسم اصلی اول. در انگلیسی اسم توصیفی اول می‌آید: chair warranty."}},"errorWatch":[{"find":["warranty of chair"],"fix":{"en":"Put the describing noun first: \"chair warranty\".","tr":"Niteleyen ismi öne koy: \"chair warranty\".","fa":"اسم توصیفی را اول بگذار: «chair warranty»."}}]},"b2":{"id":"c-ai-13-b2","level":"B2","course":"ai-internet","unit":"ai-13","track":"B2","title":"Research words: peer-reviewed, abstract, cited by","titleTr":"Araştırma kelimeleri: peer-reviewed, abstract, cited by","titleFa":"کلمه‌های تحقیق: peer-reviewed، abstract، cited by","formsTable":{"headers":{"en":["Word","Meaning"],"tr":["Kelime","Anlam"],"fa":["کلمه","معنی"]},"rows":[["peer-reviewed","checked by other experts"],["abstract","a short summary of a paper"],["cited by","other papers that use this one"]]},"wrong":"a paper peer-reviewed","right":"a peer-reviewed paper","blank":{"sentence":"This is a ___ paper.","word":"peer-reviewed","distractors":["reviewed-peer","peer review of"]},"wrong2":"I could read only the summary of abstract.","right2":"I could read only the abstract.","blank2":{"sentence":"I could read only the ___.","word":"abstract","distractors":["abstracts of","abstract of"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Peer-reviewed comes before the noun.","tr":"peer-reviewed ismin önüne gelir.","fa":"peer-reviewed پیش از اسم می‌آید.","ex":"a peer-reviewed paper"},{"en":"Say what you could not read.","tr":"Neyi okuyamadığını söyle.","fa":"بگو چه چیزی را نتوانستی بخوانی.","ex":"I could read only the abstract."}],"test":{"en":"Did you read the full text, or only the abstract?","tr":"Tam metni mi, yalnızca özeti mi okudun?","fa":"متن کامل را خواندی یا فقط چکیده را؟"}},"errorWatch":[{"find":["paper peer-reviewed"],"fix":{"en":"Put it before the noun.","tr":"İsmin önüne koy.","fa":"پیش از اسم بگذار."}}],"useIn":{"en":"B2: in your plan, name one peer-reviewed source and say what you could not read.","tr":"B2: Planında hakemli bir kaynak söyle ve neyi okuyamadığını belirt.","fa":"B2: در برنامه‌ات یک منبع داوری‌شده را معرفی کن و بگو چه چیزی را نتوانستی بخوانی."},"exitItem":{"from":"ai-13","kind":"blank","prompt":"I could read only the ___ of the paper, not the full text.","options":["abstract","cited by","thread"],"correct":0}},"vocab":{"id":"c-ai-13-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-13","goals":["career"],"title":{"en":"Places to look","tr":"Bakılacak yerler","fa":"جاهایی برای گشتن"},"cards":[{"word":"official","sentence":"Use the official page of the ministry.","meaning":{"en":"From the organisation in charge.","tr":"Yetkili kurumdan gelen.","fa":"از نهاد مسئول."}},{"word":"datasheet","sentence":"The datasheet lists the maximum temperature.","meaning":{"en":"A page of product specifications.","tr":"Ürün özelliklerini veren sayfa.","fa":"صفحه‌ی مشخصات محصول."}},{"word":"thread","sentence":"I found a useful thread on a forum.","meaning":{"en":"A forum discussion on one topic.","tr":"Tek konuda forum tartışması.","fa":"بحث در فروم درباره‌ی یک موضوع."}},{"word":"transcript","sentence":"Read the transcript of the video.","meaning":{"en":"The words of a talk in writing.","tr":"Bir konuşmanın yazılı hâli.","fa":"متن نوشتاری یک گفتار."}}]},"judge":{"id":"c-ai-13-j","course":"ai-internet","unit":"ai-13","type":"judge","title":{"en":"Where do you start?","tr":"Nereden başlarsın?","fa":"از کجا شروع می‌کنی؟"},"prompt":"Sort each question by where to start.","parts":["Maker's datasheet","Standards body","Google Scholar","Forum"],"instruction":{"en":"Choose one starting place for each question.","tr":"Her soru için bir başlangıç yeri seç.","fa":"برای هر سؤال یک نقطه‌ی شروع انتخاب کن."},"mode":"single","items":[{"by":"Example question","answer":"Does this pump work at 60 °C?","present":["Maker's datasheet"],"fix":{"en":"It is a product fact.","tr":"Bu bir ürün bilgisi.","fa":"این اطلاعات محصول است."}},{"by":"Example question","answer":"What does the rule say about fire doors?","present":["Standards body"],"fix":{"en":"Go to who wrote the rule.","tr":"Kuralı yazana git.","fa":"سراغ نویسنده‌ی قانون برو."}},{"by":"Example question","answer":"What does research say about remote work and output?","present":["Google Scholar"],"fix":{"en":"Look for peer-reviewed papers.","tr":"Hakemli makalelere bak.","fa":"دنبال مقاله‌های داوری‌شده بگرد."}},{"by":"Example question","answer":"Did other users have this error after an update?","present":["Forum"],"fix":{"en":"It is real experience, and unverified.","tr":"Gerçek deneyimdir, doğrulanmamıştır.","fa":"تجربه‌ی واقعی است، ولی تأییدنشده."}}]},"speaking":{"id":"ai-13","course":"ai-internet","unit":"ai-13","topic":{"en":"Explain your search plan","tr":"Arama planını açıkla","fa":"برنامه‌ی جست‌وجویت را توضیح بده"},"warmup":{"en":"Where do you usually look first when you need information?","tr":"Bilgi gerekince genelde ilk nereye bakarsın?","fa":"وقتی اطلاعات لازم داری معمولاً اول کجا را نگاه می‌کنی؟"},"questions":[{"en":"Tell a colleague where you would start for one question, and why not somewhere else.","tr":"Bir meslektaşına bir soru için nereden başlayacağını ve neden başka yer olmadığını söyle.","fa":"به همکارت بگو برای یک سؤال از کجا شروع می‌کنی و چرا جای دیگر نه."},{"en":"A colleague wants to check a legal rule on a forum. Say where they should start, and why.","tr":"Bir meslektaşın yasal bir kuralı forumda kontrol etmek istiyor. Nereden başlaması gerektiğini ve nedenini söyle.","fa":"همکارت می‌خواهد یک قانون را در فروم بررسی کند. بگو از کجا باید شروع کند و چرا."},{"en":"Turn this question into search terms, aloud: \"What is the delivery price to Germany?\"","tr":"Bu soruyu yüksek sesle arama terimlerine çevir: \"What is the delivery price to Germany?\"","fa":"این سؤال را بلند به کلیدواژه تبدیل کن: «What is the delivery price to Germany?»"}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"For this, I'd start with...","meaning":{"en":"Names a place.","tr":"Bir yer söyler.","fa":"یک جا را می‌گوید."}},{"phrase":"A forum may be useful, but...","meaning":{"en":"Gives a limit.","tr":"Bir sınır söyler.","fa":"یک محدودیت می‌گوید."}}],"model":"For this question, I'd start with the maker's datasheet, because we need one exact number. A forum may be useful, but it's only what people say, so I'd look there later. I'd search for the model number and the word datasheet. If the table doesn't answer it, I'd write to the supplier and ask them to confirm it.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I said why I chose that place.","tr":"O yeri neden seçtiğimi söyledim.","fa":"گفتم چرا آن جا را انتخاب کردم."}]},"writing":{"id":"c-ai-13-w","title":{"en":"A three-line search plan","tr":"Üç satırlık arama planı","fa":"برنامه‌ی جست‌وجوی سه‌خطی"},"course":"ai-internet","unit":"ai-13","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"ai-final-3","prompt":{"en":"Write a three-line plan for this question: Can our packaging go to the EU with this label? Give the question, where you will start and why, and your search terms.","tr":"Şu soru için üç satırlık plan yaz: Can our packaging go to the EU with this label? Soruyu, nereden başlayacağını ve nedenini, arama terimlerini yaz.","fa":"برای این سؤال برنامه‌ی سه‌خطی بنویس: Can our packaging go to the EU with this label? سؤال، اینکه از کجا شروع می‌کنی و چرا، و کلیدواژه‌هایت را بنویس."},"model":"Question: Can our packaging go to the EU with this label?\nStart: For a rule, start with the official EU page, because a forum may be wrong.\nSearch: EU packaging label rules \"food contact\" -blog","frame":"Question: ___\nStart: For ___, start with ___, because ___.\nSearch: ___","words":[{"word":"start with"},{"word":"because"}],"minWords":15,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Name one peer-reviewed source and what you could not read.","tr":"B2 yolu: hazır çerçeve yok. Hakemli bir kaynak ve okuyamadığın şeyi söyle.","fa":"مسیر B2: چارچوب آماده نداری. یک منبع داوری‌شده و چیزی را که نتوانستی بخوانی بگو."},"own":{"en":"Now use one real question from your work. If a site does not open for you, choose another place and say so.","tr":"Şimdi işinden gerçek bir soru kullan. Bir site açılmıyorsa başka bir yer seç ve bunu söyle.","fa":"حالا از یک سؤال واقعی در کارت استفاده کن. اگر سایتی باز نشد جای دیگری انتخاب کن و این را بگو."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Run your search. Note which page answered best.","tr":"Aramanı yap. Hangi sayfanın en iyi yanıtladığını not et.","fa":"جست‌وجویت را انجام بده و بنویس کدام صفحه بهتر جواب داد."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"You can write the plan without opening anything. The plan is the task.","tr":"Planı hiçbir şey açmadan yazabilirsin. Görev plandır.","fa":"می‌توانی بدون باز کردن چیزی برنامه را بنویسی. تمرین همین برنامه است."},"noTool":true}]},"exit":{"id":"c-ai-13-x","course":"ai-internet","unit":"ai-13","type":"exit","items":[{"from":"ai-13","kind":"mcq","prompt":"You need the maximum temperature of a product. Where do you start?","options":["The maker's datasheet","A forum","A video about the brand"],"correct":0,"why":{"en":"It is a product fact.","tr":"Bu bir ürün bilgisi.","fa":"این اطلاعات محصول است."},"point":1},{"from":"ai-13","kind":"blank","prompt":"Search for: delivery ___ Germany.","options":["price","of price","price of the"],"correct":0,"why":{"en":"Noun + noun, with no of.","tr":"İsim + isim, of olmadan.","fa":"اسم + اسم، بدون of."},"point":3},{"from":"ai-13","kind":"mcq","prompt":"What does a minus sign do in a search?","options":["Finds a number","Removes a word","Adds a word"],"correct":1,"why":{"en":"office chair -gaming removes gaming.","tr":"office chair -gaming, gaming'i çıkarır.","fa":"office chair -gaming کلمه‌ی gaming را حذف می‌کند."},"point":2},{"from":"ai-12","kind":"mcq","prompt":"The link in the answer fails, and you can't find the title. What do you write?","options":["I could not confirm this.","It is true.","It is the best study."],"correct":0,"why":{"en":"It may be invented.","tr":"Uydurma olabilir.","fa":"شاید ساختگی باشد."}},{"from":"ai-10","kind":"blank","prompt":"The draft says May, ___ the sheet says June.","options":["so","but","because"],"correct":1,"why":{"en":"But shows the difference.","tr":"but farkı gösterir.","fa":"but تفاوت را نشان می‌دهد."}},{"from":"ai-5","kind":"mcq","prompt":"What does \"say so\" ask the tool to do?","options":["Say the answer more politely.","Say that the fact is not there.","Repeat the last answer again."],"correct":1,"why":{"en":"If it is not in the text, it must tell you.","tr":"Metinde yoksa bunu söylemeli.","fa":"اگر در متن نیست، باید این را بگوید."}}]},"explain":{"id":"c-ai-13-e","course":"ai-internet","unit":"ai-13","type":"explain","level":"B1","title":{"en":"Where to look and how to search","tr":"Nereye bakmalı, nasıl aramalı","fa":"کجا بگردی و چطور جست‌وجو کنی"},"objective":{"en":"In this lesson you will learn to choose where to start for a question, and to turn it into English search terms.","tr":"Bu derste bir soru için nereden başlayacağını seçmeyi ve onu İngilizce arama terimlerine çevirmeyi öğreneceksin.","fa":"در این درس یاد می‌گیری برای یک سؤال انتخاب کنی از کجا شروع کنی و آن را به کلیدواژه‌ی انگلیسی تبدیل کنی."},"hook":{"en":"The question decides the place. A maker's datasheet answers what a forum can only guess.","tr":"Yeri soru belirler. Üreticinin teknik föyü, forumun ancak tahmin edebildiğini yanıtlar.","fa":"سؤال جای جست‌وجو را تعیین می‌کند. دیتاشیت سازنده به چیزی جواب می‌دهد که فروم فقط حدس می‌زند."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"25"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"3"}],"points":[{"head":{"en":"Which place for which question","tr":"Hangi soru için hangi yer","fa":"برای هر سؤال کدام جا"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"steps":[{"en":"You need the right words: try Wikipedia or AI search.","tr":"Doğru kelimeler lazım: Wikipedia ya da yapay zekâlı arama.","fa":"کلمه‌ی درست لازم داری: ⁨Wikipedia⁩ یا جست‌وجوی هوش مصنوعی.","ex":"What is this part called in English?"},{"en":"A specific page: Google or Bing.","tr":"Belirli bir sayfa: Google ya da Bing.","fa":"یک صفحه‌ی مشخص: ⁨Google⁩ یا ⁨Bing⁩.","ex":"maker name datasheet"},{"en":"What research says: Google Scholar.","tr":"Araştırma ne diyor: Google Scholar.","fa":"تحقیق چه می‌گوید: ⁨Google Scholar⁩.","ex":"Cited by, Since year, All versions"},{"en":"A rule or standard: the standards body or ministry.","tr":"Kural ya da standart: standart kurumu ya da bakanlık.","fa":"قانون یا استاندارد: نهاد استاندارد یا وزارتخانه.","ex":"ISO. Often only a summary is free."},{"en":"What a product can do: the maker's datasheet or manual.","tr":"Ürün ne yapabilir: üreticinin teknik föyü ya da kılavuzu.","fa":"محصول چه می‌تواند: دیتاشیت یا راهنمای سازنده.","ex":"Does it work on 110 V?"},{"en":"What people experienced: forums. Useful, but unverified.","tr":"İnsanlar ne yaşadı: forumlar. Yararlı ama doğrulanmamış.","fa":"تجربه‌ی آدم‌ها: فروم‌ها. مفید، ولی تأییدنشده.","ex":"Reddit, Stack Exchange"},{"en":"How to do it: YouTube. Check the channel and date.","tr":"Nasıl yapılır: YouTube. Kanala ve tarihe bak.","fa":"چطور انجامش بدهی: ⁨YouTube⁩. کانال و تاریخ را ببین.","ex":"Use captions."}],"tip":{"en":"Some sites may not open in your country. The lesson's examples work without them. This table is a starting point, not a rule.","tr":"Bazı siteler ülkende açılmayabilir. Dersin örnekleri onlarsız da çalışır. Bu liste kural değil, başlangıç noktasıdır.","fa":"شاید بعضی سایت‌ها در کشورت باز نشوند. مثال‌های این درس بدون آن‌ها هم کار می‌کنند. این فهرست نقطه‌ی شروع است، نه قانون."}},{"head":{"en":"Turn a question into key words","tr":"Soruyu anahtar kelimelere çevir","fa":"سؤال را به کلیدواژه تبدیل کن"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"steps":[{"en":"Drop the small words. Keep the nouns.","tr":"Küçük kelimeleri at. İsimleri tut.","fa":"کلمه‌های کوچک را حذف کن. اسم‌ها را نگه دار.","ex":"office chair warranty period"},{"en":"Use quotes for an exact phrase.","tr":"Tam ifade için tırnak kullan.","fa":"برای عبارت دقیق از گیومه استفاده کن.","ex":"\"office chair\""},{"en":"Use a minus sign to remove a word.","tr":"Bir kelimeyi çıkarmak için eksi işareti kullan.","fa":"برای حذف یک کلمه از علامت منفی استفاده کن.","ex":"office chair -gaming"},{"en":"Use filters such as Forums, Videos and Books.","tr":"Forums, Videos ve Books gibi filtreler kullan.","fa":"از فیلترهایی مثل ⁨Forums⁩، ⁨Videos⁩ و ⁨Books⁩ استفاده کن.","ex":"Filter: Forums"}],"phrases":[{"phrase":"I need to search in English. My question: [your question in your language]. Give me five English search terms and the usual English name for this thing. Do not answer the question.","meaning":{"en":"Find the words first. Then search yourself.","tr":"Önce kelimeleri bul. Sonra aramayı kendin yap.","fa":"اول کلمه‌ها را پیدا کن. بعد خودت جست‌وجو کن."},"copy":true}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Noun + noun, and for X, start with Y","tr":"İsim + isim ve for X, start with Y","fa":"اسم + اسم و ⁨for X, start with Y⁩"},"steps":[{"en":"The describing noun goes first, with no of.","tr":"Niteleyen isim öne gelir, of olmadan.","fa":"اسم توصیفی اول می‌آید، بدون ⁨of⁩.","ex":"chair warranty"},{"en":"Recommend a place with for + noun, start with.","tr":"Yeri for + isim, start with ile öner.","fa":"جا را با ⁨for⁩ + اسم، ⁨start with⁩ پیشنهاد بده.","ex":"For specifications, start with the datasheet."}],"table":{"headers":{"en":["Not this","This"],"tr":["Bu değil","Bu"],"fa":["این نه","این"]},"rows":[["warranty of a chair","chair warranty"],["period of warranty","warranty period"],["price of delivery","delivery price"]]},"tip":{"en":"Persian and Turkish often put the main noun first or use a suffix. English search terms put the describing noun first: chair warranty.","tr":"Türkçede \"sandalye garantisi\" derken ek kullanılır. İngilizcede ek yoktur, sıra yeter: chair warranty.","fa":"در فارسی می‌گوییم «گارانتی صندلی»، با اسم اصلی اول. در انگلیسی اسم توصیفی اول می‌آید: ⁨chair warranty⁩."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From question to plan","tr":"Sorudan plana","fa":"از سؤال تا برنامه"},"item":"Does this coffee machine, the Baro 200, work on 110 V?","answer":"Place: the maker's datasheet. Search: Baro 200 datasheet \"voltage\". Then ask the supplier if it is not clear.","walk":[{"en":"What kind of question? A product fact.","tr":"Ne tür bir soru? Ürün bilgisi.","fa":"چه نوع سؤالی است؟ اطلاعات محصول."},{"en":"Choose the place: the maker, not a forum.","tr":"Yeri seç: Forum değil, üretici.","fa":"جا را انتخاب کن: سازنده، نه فروم."},{"en":"Write nouns, and quote the exact phrase.","tr":"İsimleri yaz, tam ifadeyi tırnağa al.","fa":"اسم‌ها را بنویس و عبارت دقیق را در گیومه بگذار."}]},"quick":{"prompt":"Which is the best search for \"How long is the warranty on an office chair?\"","options":["how long is it please","office chair warranty period","warranty of the chair of the office"],"correct":1,"why":{"en":"It keeps the nouns and drops the small words.","tr":"İsimleri tutar, küçük kelimeleri atar.","fa":"اسم‌ها را نگه می‌دارد و کلمه‌های کوچک را حذف می‌کند."}},"remember":{"en":"For the question, choose the place. For the place, write the key words.","tr":"Soruya göre yeri seç. Yere göre anahtar kelimeleri yaz.","fa":"با توجه به سؤال جا را انتخاب کن و با توجه به جا کلیدواژه بنویس."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Research words: peer-reviewed, abstract, cited by","tr":"Araştırma kelimeleri: peer-reviewed, abstract, cited by","fa":"کلمه‌های تحقیق: ⁨peer-reviewed⁩، ⁨abstract⁩، ⁨cited by⁩"},"steps":[{"en":"Peer-reviewed comes before the noun.","tr":"peer-reviewed ismin önüne gelir.","fa":"⁨peer-reviewed⁩ پیش از اسم می‌آید.","ex":"a peer-reviewed paper"},{"en":"Say what you could not read.","tr":"Neyi okuyamadığını söyle.","fa":"بگو چه چیزی را نتوانستی بخوانی.","ex":"I could read only the abstract."}],"table":{"headers":{"en":["Word","Meaning"],"tr":["Kelime","Anlam"],"fa":["کلمه","معنی"]},"rows":[["peer-reviewed","checked by other experts"],["abstract","a short summary of a paper"],["cited by","other papers that use this one"]]},"body":{"en":"B2: in your plan, name one peer-reviewed source and say what you could not read.","tr":"B2: Planında hakemli bir kaynak söyle ve neyi okuyamadığını belirt.","fa":"⁨B2⁩: در برنامه‌ات یک منبع داوری‌شده را معرفی کن و بگو چه چیزی را نتوانستی بخوانی."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
